return $input.all().map(i => {
  const t = i.json;
  return { json: {
    caso_id: String(t.id_ticket),
    codigo: 'MV-' + t.id_ticket,
    canal: t.canal || 'email',
    email_cliente: t.email_cliente || '',
    texto: (t.assunto ? t.assunto + ' - ' : '') + (t.descricao || ''),
    categoria: t.tipo_ticket || 'OUTROS',
    subcategoria: t.assunto || '',
    confianca: Number(t.confianca_classificacao || 0),
    urgencia_calculada: Number(t.urgencia_calculada || 0),
    irritacao: Number(t.irritacao_nivel || 0),
    prioridade_declarada: t.prioridade_declarada || 'normal',
    motivo_humano: ''
  } };
});

const ctx = $('Contexto').first().json;
const cat = String(ctx.categoria || '').toLowerCase();
let p = { categoria: ctx.categoria, ia_pode_resolver: true, exige_retencao: false, teto_valor: null, texto_regra: 'Politica padrao: IA pode resolver com base em precedente.' };
if (cat.includes('cancel')) { p.ia_pode_resolver = false; p.exige_retencao = true; p.texto_regra = 'Cancelamentos exigem retencao humana.'; }
else if (cat.includes('refund') || cat.includes('reembolso')) { p.teto_valor = 200; p.texto_regra = 'Reembolso ate R$200 pode ser resolvido pela IA com precedente.'; }
else if (cat.includes('billing') || cat.includes('cobranca')) { p.teto_valor = 100; p.texto_regra = 'Ajustes de cobranca ate R$100 podem ser resolvidos pela IA.'; }
else if (cat.includes('technical') || cat.includes('tecnico')) { p.texto_regra = 'Suporte tecnico pode ser resolvido pela IA com precedente.'; }
else if (cat.includes('inquiry') || cat.includes('duvida')) { p.texto_regra = 'Duvidas de produto podem ser respondidas pela IA com precedente.'; }
return [{ json: p }];

const ctx = $('Contexto').first().json;
const rows = $input.all().map(i => i.json);
const pol = rows[0] || {};
let motivo = '';
let iaPode = true;
if (rows.length === 0) { iaPode = false; motivo = 'OUTROS'; }
else if (pol.ia_pode_resolver === false) { iaPode = false; motivo = pol.exige_retencao ? 'RETENCAO' : 'OUTROS'; }
return [{ json: {
  caso_id: ctx.caso_id, codigo: ctx.codigo, canal: ctx.canal, email_cliente: ctx.email_cliente,
  texto: ctx.texto, categoria: ctx.categoria, subcategoria: ctx.subcategoria, confianca: ctx.confianca,
  urgencia_calculada: ctx.urgencia_calculada, irritacao: ctx.irritacao, prioridade_declarada: ctx.prioridade_declarada,
  ia_pode_resolver: iaPode,
  teto_valor: (pol.teto_valor === undefined ? null : pol.teto_valor),
  exige_retencao: !!pol.exige_retencao,
  texto_regra: pol.texto_regra || 'Sem padrao conhecido. Sempre humano.',
  fonte: 'FICTICIO_DEMO',
  motivo_humano: motivo
} }];

const base = $('Avalia politica').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.resolucao_texto && String(r.resolucao_texto).trim() !== '' && String(r.id_ticket) !== String(base.caso_id));
const best = rows[0] || null;
const sim = best ? 0.85 : 0;
const tem = sim >= 0.80;
return [{ json: { ...base, similaridade: sim, texto_solucao: best ? best.resolucao_texto : '', precedente_id: best ? best.id_ticket : null, tem_precedente: tem, motivo_humano: tem ? '' : 'SEM_PRECEDENTE' } }];

