const base = $('Avalia precedente').first().json;
const out = ($input.all()[0] && $input.all()[0].json.output) ? $input.all()[0].json.output : {};
const valor = Number(out.valor || 0);
let motivo = '';
if (String(out.acao || '').toUpperCase() === 'ESCALAR') motivo = 'SEM_PRECEDENTE';
else if (base.teto_valor != null && valor > Number(base.teto_valor)) motivo = 'LIMITE';
else if (base.exige_retencao) motivo = 'RETENCAO';
return [{ json: { ...base, acao_proposta: out.acao || 'ESCALAR', valor_proposto: valor, justificativa: out.justificativa || '', fonte_resposta: out.fonte || '', resposta: out.justificativa || '', motivo_humano: motivo } }];

